'use strict';
const $=id=>document.getElementById(id);let curriculum=[],grade=1,current=null,modelId='',state={},discoveries={};
try{discoveries=JSON.parse(localStorage.getItem('math-discovery-v1')||'{}');if(!discoveries||Array.isArray(discoveries)||typeof discoveries!=='object')discoveries={}}catch(e){discoveries={}}
const terms=['','First Term','Second Term','Third Term'];
function defaults(id){return Object.fromEntries(M[id].controls.filter(c=>c.type!=='button').map(c=>[c.key,c.value]))}
function updateCount(){$('count').textContent=Object.keys(discoveries).length}
function thumb(id){let m=M[id];let [v]=m.render(defaults(id));if(v.startsWith('<svg'))return v;return svg(txt(300,155,id==='expression'?'(8 + 4) × 3':id==='powers'?'√16 = 4':id==='ordinal'?'1st · 2nd · 3rd':id==='factors'?'2 · 3 · 5 · 7':'3 · 5 · 7',38)+txt(300,220,'Explore the pattern',18))}
function filtered(){let term=+$('term').value,week=+$('week').value,q=$('search').value.toLowerCase().trim();return curriculum.filter(r=>r.grade===grade&&(!term||r.term===term)&&(!week||(()=>{let w=r.weeks.match(/\d+/g).map(Number);return week>=w[0]&&week<=w.at(-1)})())&&(!q||(r.text+' '+r.models.map(id=>M[id].title).join(' ')).toLowerCase().includes(q)))}
function renderCards(){document.querySelectorAll('.grades button').forEach(b=>{let active=+b.dataset.grade===grade;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});let rows=filtered();$('resultsTitle').textContent=`Grade ${grade} discoveries`;$('resultsCount').textContent=rows.length+' competency groups';$('cards').innerHTML=rows.length?rows.map(r=>`<button class="card" data-id="${r.id}"><div class="thumb"><span class="tag">${r.models.length} ${r.models.length===1?'model':'models'}</span>${thumb(r.models[0])}</div><div class="card-body"><div class="meta">${terms[r.term]} · Week ${r.weeks}</div><h3>${esc(M[r.models[0]].title)}</h3><p>${esc(r.competencies[0]||r.text)}</p><div class="card-bottom"><span>${r.models.some(m=>discoveries[r.id+':'+m])?'✓ Discovery saved':'Explore · Predict · Explain'}</span><strong>Open lab</strong></div></div></button>`).join(''):'<div class="empty">No matching competencies. Try another topic, term, or week.</div>';document.querySelectorAll('.card').forEach(b=>b.addEventListener('click',()=>openLab(b.dataset.id)));}
function chooseGrade(g){grade=g;renderCards();history.replaceState(null,'','#grade='+g)}
function openLab(id,selected){current=curriculum.find(r=>r.id===id);if(!current)return;$('labMeta').textContent=`Grade ${current.grade} / ${terms[current.term]} / Week ${current.weeks}`;$('competencyText').innerHTML='<ul>'+current.competencies.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><p class="note">Source: '+esc(current.source)+'. Competency wording is extracted from the supplied PDF; mathematical superscripts and line breaks may be simplified by PDF extraction.</p><p class="note">Choose a companion model below. Each model explores a specific idea; the complete weekly competencies may also require contextual problems, constructions, or written proofs.</p>';$('labTabs').innerHTML=current.models.map(id=>`<button data-model="${id}">${esc(M[id].title)}</button>`).join('');$('labTabs').querySelectorAll('button').forEach(b=>b.onclick=()=>selectModel(b.dataset.model));if(!$('lab').open)$('lab').showModal();selectModel(selected&&current.models.includes(selected)?selected:current.models[0]);}
function selectModel(id){modelId=id;let prior=discoveries[current.id+':'+id];state=defaults(id);if(prior&&prior.state)for(let c of M[id].controls){let v=prior.state[c.key];if(v!==undefined&&c.type!=='button')state[c.key]=c.type==='range'||c.type==='number'?Math.max(c.min,Math.min(c.max,Number(v)||0)):v}if(!prior){if(id==='place'){state.n=current.grade===1?42:current.grade===2?356:current.grade===3?2547:438215;if(/decimal/i.test(current.text)){state.digits=current.grade===4?2:current.grade===5?3:4;state.n=3456}}if(id==='fraction'&&current.grade===1){state.a=1;state.b=2;state.c=1;state.d=4}if(id==='data'){if(/double bar/i.test(current.text))state.view='Double bar graph';else if(/double line/i.test(current.text))state.view='Double line graph';else if(/pie graph/i.test(current.text))state.view='Pie graph';else if(/pictograph/i.test(current.text))state.view='Pictograph';else if(/box-and-whisker/i.test(current.text))state.view='Box plot';else if(/line graph/i.test(current.text))state.view='Line graph'}if(id==='fraction'){if(/multiply|multiplication/i.test(current.text))state.op='Multiply';else if(/divide|division/i.test(current.text))state.op='Divide';else if(/add/i.test(current.text))state.op='Add'}if(id==='numberline'&&/subtract/i.test(current.text))state.op='−';if(id==='linear'&&/system/i.test(current.text))state.view='Two lines';if(id==='angle'&&/parallel/i.test(current.text))state.view='Parallel lines & transversal';if(id==='solid'){if(/cylinder/i.test(current.text))state.shape='Cylinder';else if(/cone/i.test(current.text))state.shape='Cone';else if(/pyramid/i.test(current.text))state.shape='Square pyramid'}}$('labTitle').textContent=M[id].title;$('prompt').textContent=M[id].prompt;$('reflection').value=prior?.note||'';$('saveStatus').textContent='';$('teacherPrompt').textContent='Discussion focus: '+M[id].prompt;$('labTabs').querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.model===id);b.setAttribute('aria-pressed',b.dataset.model===id)});renderControls();draw();}
function renderControls(){$('controls').innerHTML=M[modelId].controls.map(c=>`<div class="control">${c.type==='button'?`<button class="action" data-action="${c.key}">${esc(c.label)}</button>`:`<label for="ctl-${c.key}">${esc(c.label)}${c.type==='range'?`<output id="val-${c.key}">${esc(state[c.key])}</output>`:''}</label>${c.type==='select'?`<select id="ctl-${c.key}" data-key="${c.key}">${c.options.map(v=>`<option ${state[c.key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`:`<input id="ctl-${c.key}" data-key="${c.key}" type="${c.type}" value="${esc(state[c.key])}" ${c.min!==undefined?`min="${c.min}" max="${c.max}" step="${c.step}"`:''}>`}`}</div>`).join('');$('controls').querySelectorAll('[data-key]').forEach(el=>el.addEventListener('input',()=>{let c=M[modelId].controls.find(c=>c.key===el.dataset.key),v=el.value;if(c.type==='range'||c.type==='number'){v=Number(v);if(!Number.isFinite(v))return;v=Math.min(c.max,Math.max(c.min,v))}state[c.key]=v;if(modelId==='probability'){state.trials=0;state.greenHits=0}if($('val-'+c.key))$('val-'+c.key).textContent=v;draw();$('saveStatus').textContent=''}));$('controls').querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{if(modelId==='probability'){let n=el.dataset.action==='hundred'?100:1;for(let i=0;i<n;i++){let t=state.trials||0,h=state.greenHits||0,r=state.red-(state.replace==='Without replacement'?h:0),g=state.gold-(state.replace==='Without replacement'?t-h:0);if(r+g<=0)break;state.greenHits=h+(Math.random()<r/(r+g)?1:0);state.trials=t+1}draw()}})}
function draw(){try{let [pic,result]=M[modelId].render(state);$('canvas').innerHTML=pic;$('readout').innerHTML=result}catch(e){$('canvas').textContent='Please check the values entered.';$('readout').textContent='Use values within the control limits.'}}
$('reset').onclick=()=>{state=defaults(modelId);renderControls();draw();$('saveStatus').textContent='Model reset.'};$('save').onclick=()=>{let note=$('reflection').value.trim();if(!note){$('saveStatus').textContent='Write an observation or prediction first.';$('reflection').focus();return}let entry={id:current.id,model:modelId,title:M[modelId].title,grade:current.grade,term:current.term,weeks:current.weeks,note,state:{...state},date:new Date().toISOString()};try{let next={...discoveries,[current.id+':'+modelId]:entry};localStorage.setItem('math-discovery-v1',JSON.stringify(next));discoveries=next;updateCount();renderCards();$('saveStatus').textContent='Saved on this device. You can find it in My discoveries.'}catch(e){$('saveStatus').textContent='This browser cannot save locally. Copy your observation before closing.'}};
$('closeLab').onclick=()=>{$('lab').close();if(document.fullscreenElement)document.exitFullscreen?.()};$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('lab').requestFullscreen()}catch(e){$('saveStatus').textContent='Fullscreen is not available in this browser.'}};
$('info').querySelector('.close-info').onclick=()=>$('info').close();
$('teacher').onclick=()=>{$('infoBody').innerHTML='<p class="eyebrow">TEACH WITH CURIOSITY</p><h2>Give ideas room to grow.</h2><p>Choose the grade, term, and week from your Budget of Work. Open a lab and expand the competencies to see the source wording.</p><ol><li><b>Explore:</b> Give learners two minutes to investigate the model.</li><li><b>Predict:</b> Ask what will happen before moving a control.</li><li><b>Explain:</b> Compare examples and justify the pattern.</li><li><b>Extend:</b> Use a local context, written solution, or proof to address the full competency.</li></ol><p>Use Expand for classroom projection. All controls work with keyboard input and touch. Notes are stored only in the current browser, without names or accounts. Shared devices share the same notes.</p><p><b>Coverage:</b> 254 source competency groups cover all 300 grade–term–week slots. Companion models illustrate selected concepts within each group; this is not a claim of complete assessment or mastery of every competency.</p><p><a href="https://phet.colorado.edu/en/teaching-resources/virtual-workshop/math" target="_blank" rel="noopener">Read PhET’s mathematics teaching guidance</a>. These original models are independent of PhET and SPSTEM.</p>';$('info').showModal()};
$('progress').onclick=()=>{let entries=Object.entries(discoveries);$('infoBody').innerHTML='<p class="eyebrow">YOUR EXPLORATION NOTEBOOK</p><h2>My discoveries</h2><p>Saved in this browser only. Export your notes to keep a copy.</p>'+ (entries.length?'<button id="exportNotes">Export notes</button>'+entries.map(([key,e])=>`<article class="discovery"><b>${esc(e.title)} · Grade ${e.grade}</b><p>${terms[e.term]} · Week ${esc(e.weeks)}</p><p>${esc(e.note)}</p><button data-reopen="${esc(key)}">Reopen model</button></article>`).join(''):'<p>No discoveries saved yet. Explore a model, write what you notice, and select Save discovery.</p>');$('infoBody').querySelectorAll('[data-reopen]').forEach(b=>b.onclick=()=>{let e=discoveries[b.dataset.reopen];$('info').close();openLab(e.id,e.model)});if($('exportNotes'))$('exportNotes').onclick=()=>{let text=entries.map(([,e])=>`${e.title}\nGrade ${e.grade} | ${terms[e.term]} | Week ${e.weeks}\n${e.note}\n`).join('\n'),url=URL.createObjectURL(new Blob([text],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download='Math_Discovery_Notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('info').showModal()};
$('grades').innerHTML=Array.from({length:10},(_,i)=>`<button data-grade="${i+1}"><span>GRADE</span><b>${i+1}</b></button>`).join('');$('grades').querySelectorAll('button').forEach(b=>b.onclick=()=>chooseGrade(+b.dataset.grade));for(let i=1;i<=10;i++)$('week').insertAdjacentHTML('beforeend',`<option value="${i}">${i}</option>`);['term','week','search'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',renderCards));updateCount();fetch('curriculum.json').then(r=>{if(!r.ok)throw Error('load');return r.json()}).then(data=>{curriculum=data;let g=Number(location.hash.match(/grade=(\d+)/)?.[1]);if(g>=1&&g<=10)grade=g;renderCards()}).catch(()=>$('cards').innerHTML='<div class="empty">The competency list could not load. Please refresh the page when your connection is available.</div>');
